using System.Runtime.InteropServices;
using MicroEngine.Core;
using MicroEngine.Input;
using Rl = Raylib_cs.Raylib;

namespace MicroEngine.Raylib.Tests;

/// <summary>
/// The desktop keyboard path end to end on Linux: key events are generated by the X server (XTEST, as a physical
/// keyboard would), raylib/GLFW receives them in a visible window, and the engine reads them through RaylibInput and
/// InputMap, frame by frame as the game loop does. Scripts never take this path: they force actions on InputMap.
/// Gamepads are not covered.
/// </summary>
[TestClass]
[TestCategory("Native")]
[OSCondition(OperatingSystems.Linux, IgnoreMessage = "Keyboard injection uses the X server's XTEST extension.")]
[DoNotParallelize]
public sealed partial class KeyboardTests
{
    private const nint XkSpace = 0x20, XkLeft = 0xff51;

    [LibraryImport("libX11.so.6")] private static partial nint XOpenDisplay(nint name);
    [LibraryImport("libX11.so.6")] private static partial int XCloseDisplay(nint display);
    [LibraryImport("libX11.so.6")] private static partial byte XKeysymToKeycode(nint display, nint keysym);
    [LibraryImport("libX11.so.6")] private static partial int XSync(nint display, int discard);
    [LibraryImport("libXtst.so.6")] private static partial int XTestQueryExtension(nint display, out int eventBase, out int errorBase, out int major, out int minor);
    [LibraryImport("libXtst.so.6")] private static partial int XTestFakeKeyEvent(nint display, uint keycode, int isPress, nuint delay);
    [LibraryImport("libXtst.so.6")] private static partial int XTestFakeMotionEvent(nint display, int screen, int x, int y, nuint delay);

    private nint _display;
    private RaylibPlatform? _platform;
    private readonly InputMap _map = new InputMap().Bind("jump", Key.Space).Bind("left", Key.Left);

    [TestInitialize]
    public void Open()
    {
        Native.Require(!string.IsNullOrEmpty(Environment.GetEnvironmentVariable("DISPLAY")), "No X display (run under xvfb-run).");
        try { _display = XOpenDisplay(0); }
        catch (DllNotFoundException e) { Native.Require(false, $"libX11/libXtst missing: {e.Message}"); }
        Native.Require(_display != 0, "Cannot open the X display.");
        Native.Require(XTestQueryExtension(_display, out _, out _, out _, out _) != 0, "The X server has no XTEST extension.");
        // A visible window: keyboard focus follows the pointer when no window manager runs (Xvfb), so the pointer is
        // moved over the window before any key is sent.
        _platform = new RaylibPlatform(new GameSettings("keyboard test", 160, 90, 2), new DesktopOptions(Mute: true));
        for (int i = 0; i < 5; i++) Frame();
        var at = Rl.GetWindowPosition();
        XTestFakeMotionEvent(_display, -1, (int)at.X + 160, (int)at.Y + 90, 0);
        XSync(_display, 0);
        for (int i = 0; i < 5; i++) Frame();
    }

    [TestCleanup]
    public void Close()
    {
        _platform?.Dispose();
        if (_display != 0) XCloseDisplay(_display);
    }

    private (bool Down, bool Pressed, bool Released) Frame()
    {
        _platform!.PollEvents();
        _map.Sample(_platform.Input);
        var state = (_map.Down("jump"), _map.Pressed("jump"), _map.Released("jump"));
        _map.EndUpdate();
        _platform.BeginFrame();
        _platform.EndFrame(); // raylib reads the window's events here
        Thread.Sleep(5);
        return state;
    }

    private void Send(nint keysym, bool press)
    {
        XTestFakeKeyEvent(_display, XKeysymToKeycode(_display, keysym), press ? 1 : 0, 0);
        XSync(_display, 0);
    }

    private List<(bool Down, bool Pressed, bool Released)> Frames(int count) => [.. Enumerable.Range(0, count).Select(_ => Frame())];

    [TestMethod]
    public void A_held_key_is_pressed_once_stays_down_and_is_released()
    {
        Send(XkSpace, press: true);
        var held = Frames(20);
        int first = held.FindIndex(f => f.Down);
        Assert.IsTrue(first is >= 0 and <= 3, $"The key reached the engine within a few frames (frame {first}).");
        Assert.AreEqual(1, held.Count(f => f.Pressed), "One press edge for one key press.");
        Assert.IsTrue(held.Skip(first).All(f => f.Down), "Down on every frame while held.");
        Assert.IsFalse(held.Any(f => f.Released));

        Send(XkSpace, press: false);
        var after = Frames(10);
        int released = after.FindIndex(f => f.Released);
        Assert.IsTrue(released is >= 0 and <= 3, $"Released within a few frames (frame {released}).");
        Assert.AreEqual(1, after.Count(f => f.Released), "One release edge.");
        Assert.IsFalse(after.Skip(released).Any(f => f.Down), "Up after the release.");
    }

    [TestMethod]
    public void A_tap_shorter_than_a_frame_is_still_seen_once()
    {
        Send(XkSpace, press: true);
        Send(XkSpace, press: false); // both edges arrive before raylib polls: it never reports the key as down
        var frames = Frames(15);
        Assert.AreEqual(1, frames.Count(f => f.Pressed), "The tap counts as one press (RaylibInput.CollectTaps).");
        Assert.AreEqual(1, frames.Count(f => f.Released), "And is released right after.");
        Assert.IsFalse(frames[^1].Down);
    }

    [TestMethod]
    public void Two_held_keys_are_independent()
    {
        Send(XkLeft, press: true);
        Frames(4);
        Assert.IsTrue(_map.Down("left"));
        Assert.IsFalse(_map.Down("jump"), "Only the key that was pressed.");
        Send(XkSpace, press: true);
        Frames(4);
        Assert.IsTrue(_map.Down("left") && _map.Down("jump"));
        Send(XkLeft, press: false);
        Frames(4);
        Assert.IsFalse(_map.Down("left"));
        Assert.IsTrue(_map.Down("jump"), "Releasing one key leaves the other held.");
        Send(XkSpace, press: false);
        Frames(4);
        Assert.IsFalse(_map.Down("jump"));
    }
}
